mapper.select:
SELECT /*selectMasterMpStReverseMarginStatsList*/ YYYY, LAW_GROUP_CD, LAW_GROUP_NM, GROUP_CD, GROUP_NM, TEAM_CD, decode(GR,1,'소계',7,'합계',TEAM_NM) TEAM_NM, '역마진' AS GUBUN, JAN, FEB, MAR, APR, MAY, JUN, JUL, AUG, SEP, OCT, NOV, DEC, JAN+FEB+MAR+APR+MAY+JUN+JUL+AUG+SEP+OCT+NOV+DEC TOT, GR, VALUE1 FROM ( SELECT A.YYYY AS YYYY , C.GROUP_CODE AS LAW_GROUP_CD , C.GROUP_NAME AS LAW_GROUP_NM , C.CORP_CODE AS GROUP_CD , C.CORP_NAME AS GROUP_NM , A.KEP_DEPT AS TEAM_CD , D.TEXT1 AS TEAM_NM , trunc(SUM(NVL(M01, 0))) AS JAN , trunc(SUM(NVL(M02, 0))) AS FEB , trunc(SUM(NVL(M03, 0))) AS MAR , trunc(SUM(NVL(M04, 0))) AS APR , trunc(SUM(NVL(M05, 0))) AS MAY , trunc(SUM(NVL(M06, 0))) AS JUN , trunc(SUM(NVL(M07, 0))) AS JUL , trunc(SUM(NVL(M08, 0))) AS AUG , trunc(SUM(NVL(M09, 0))) AS SEP , trunc(SUM(NVL(M10, 0))) AS OCT , trunc(SUM(NVL(M11, 0))) AS NOV , trunc(SUM(NVL(M12, 0))) AS DEC , grouping_id(C.GROUP_CODE,C.CORP_CODE,A.KEP_DEPT ) GR, max(D.VALUE1) as VALUE1 FROM BNTMIS_REMARGIN A, ICOMCMPY B, BNTBUYERGROUP C, ICOMCOD2 D WHERE A.BUYER = B.COM_CODE AND B.CORP_CODE = C.CORP_CODE AND A.KEP_DEPT = D.CODE AND D.TYPE = 'C001' AND D.COMPANY_CODE = 'KRKORE0001' AND D.VALUE1 LIKE '9%'
AND A.YYYY=#{st_year}
AND A.KEP_DEPT = #{st_user_dept}
AND C.GROUP_CODE = #{st_buyer_group}
AND C.CORP_CODE = #{st_corp_code}
GROUP BY ROLLUP (A.YYYY, C.GROUP_CODE, C.GROUP_NAME, C.CORP_CODE, C.CORP_NAME, A.KEP_DEPT, D.TEXT1) ORDER BY decode(GR,1,0,7,99,0) desc, A.YYYY, C.GROUP_CODE, C.CORP_CODE, VALUE1 ASC, TEAM_CD ) WHERE (GR = 0 AND TEAM_NM IS NOT NULL) OR (GR = 1 AND GROUP_NM IS NOT NULL) OR (GR = 7 AND YYYY IS NOT NULL)
